INSERT INTO feature VALUES('claim-order','workflow','The claim order a seat walks between units',NULL,'implemented','ordinary',NULL,'`claim:next` claims an unowned defect in the area, then a `kind:refactor` in the area, then performance, gaps cheapest first and the lane''s planned units, priority first within each bucket and a blocked issue passed over. The pick is by order alone, sectioned or not: each section it lacks is printed as due, the claiming seat writes them first and pages for the coordinator''s `shape:signed`, and `pr:open` refuses a landing on an issue unsectioned or unsigned. A lane holding a claim no open pull request names claims nothing until it lands or releases it, and an issue the lane released in the last 2 hours heads its order and is passed over by every other lane.',NULL,'.config/claims/next.json .config/bodies/signed.json',NULL,NULL);
